from taf.collectors.core.factories.process_factory import ProcessFactory
from taf.collectors.core.entities.ssh_process import SshProcess, SshInputStream, SshOutputStream, SshErrorStream


class SshProcessFactory(ProcessFactory):
    def __init__(self, managed_ssh_connection, use_tty, channel_timeout=None, **kwargs):
        super(SshProcessFactory, self).__init__(**kwargs)
        self._managed_ssh_connection = managed_ssh_connection
        self._use_tty = use_tty
        self._channel_timeout = channel_timeout

    def create_process(self, command):
        ssh_process = self._managed_ssh_connection.send_command(
            command=command,
            get_pty=self._use_tty,
            timeout=self._managed_ssh_connection.channel_timeout)
        stdin = self._create_ssh_input_stream(buffered_file=ssh_process.stdin)
        stdout = self._create_ssh_output_stream(buffered_file=ssh_process.stdout)
        stderr = self._create_ssh_error_stream(buffered_file=ssh_process.stderr)
        process = SshProcess(
            command=command,
            stdin=stdin,
            stdout=stdout,
            stderr=stderr,
            ssh_process=ssh_process)
        return process

    def _create_ssh_input_stream(self, buffered_file):
        return SshInputStream(buffered_file=buffered_file, use_tty=self._use_tty)

    def _create_ssh_output_stream(self, buffered_file):
        return SshOutputStream(buffered_file=buffered_file)

    def _create_ssh_error_stream(self, buffered_file):
        return SshErrorStream(buffered_file=buffered_file)
